            axis, pos = "h", r
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis, pos = "v", c
                break
    if axis is None:
        return [row[:] for row in grid]

    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return [row[:] for row in grid]

    along = [r if axis == "h" else c for r, c, _ in cells]
    lo, hi = min(along), max(along)

    if hi < pos:
        direction = 1
        shift = max(0, pos - 1 - hi)
    elif lo > pos:
        direction = -1
        shift = max(0, lo - pos - 1)
    else:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r, c, _ in cells:
        out[r][c] = bg

    moved_along = []
    for r, c, value in cells:
        if axis == "h":
            r += direction * shift
            moved_along.append(r)
        else:
            c += direction * shift
            moved_along.append(c)
        out[r][c] = value

    # Draw an 8 line just beyond the object's trailing edge.
    trail = min(moved_along) - 1 if direction == 1 else max(moved_along) + 1
    if axis == "h" and 0 <= trail < h:
        out[trail] = [8] * w
    elif axis == "v" and 0 <= trail < w:
